-- 检查并记录角色地面材质, 可能会影响 音效类型
    

---@class FloorMaterialDetect
local FloorMaterialDetect = Class('FloorMaterialDetect')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')


---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
local FootStepState = DreamSpaceStates.FootStepState


local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---@type DesiredMultiTagsManager
local DesiredMultiTagsManager = import('Game.Utils.DesiredMultiTagsManager'):GetInstance()


---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator
local ParticleSystem = CS.UnityEngine.ParticleSystem
local QueryTriggerInteraction = CS.UnityEngine.QueryTriggerInteraction

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters
local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace


-- ========================================================


-- 地板材质专用层: 
local floorMaterialLayerMask = DreamSpaceLuaUtils.CreateLayerMask( { DreamSpaceStates.layers.FloorDetect } )


local detetctPeriod = 4 -- 每 n 帧检测一次, 降低程序开销


-- ========================================================

function FloorMaterialDetect:__init()
    self.controller = nil
    self.isInit = false

    self.frameIdx = 0
end


function FloorMaterialDetect:__delete()
    self.co_0 = nil
end



function FloorMaterialDetect:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    ---
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end



function FloorMaterialDetect:DelayInit()

    -- ----- role ------:
    -- 只会查找 N 次, 还是找不到就放弃 hint 功能了;
    self.role = nil -- 它的 pos 就是角色的 pos, 它的 forwatd 方向就是角色的当前运动方向
    for i=0, DreamSpaceStates.DelayInitWaitFrames do 
        self.role = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        if not isNull(self.role) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end
    assert( isNotNull(self.role), "始终没能找到 gamoebj: SwitchablePlayer/VTarget/Follow, 请查找原因" )

    print( "floorMaterialLayerMask= " .. floorMaterialLayerMask )

    self.isInit = true
end



function FloorMaterialDetect:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function FloorMaterialDetect:Update()
    if self.isInit ~= true then 
        return
    end 

    -- 
    self.frameIdx = self.frameIdx + 1
    if self.frameIdx > 10000000 then 
        self.frameIdx = 0
    end 

    if (self.frameIdx % detetctPeriod) ~= 0 then 
        return
    end

    self:DetectFloor()


end



-- =========================================== Self ================================================ --



function FloorMaterialDetect:DetectFloor()
    --print( "DetectFloor" )
    local upperLen = 0.4
    local lowerLen = 0.2

    if isNull(self.role) then -- !!
        return
    end 

    local srcPos = self.role.position + Vector3.up * upperLen
    local detectDistance = upperLen + lowerLen

    local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( srcPos, Vector3.down, detectDistance, floorMaterialLayerMask, QueryTriggerInteraction.Collide )
    if isHit1 == true then 
        --print( "向下命中: " .. raycastHit1.transform.name )
        local transformInstanceId = raycastHit1.transform:GetInstanceID()
        if DesiredMultiTagsManager:IsContainTag( transformInstanceId, "Glass" ) then 
            --print( "检测到 地板材质: Glass" )
            DreamSpaceStates.floorMaterial = DreamSpaceStates.FloorMaterials.Glass
            return
        end 

    end 

    DreamSpaceStates.floorMaterial = DreamSpaceStates.FloorMaterials.Default

end 



return FloorMaterialDetect

